"use strict";exports.id=6548,exports.ids=[6548],exports.modules={16548:(a,b,c)=>{c.d(b,{o:()=>k});var d=c(59740);let e=(0,d.A)("smartphone",[["rect",{width:"14",height:"20",x:"5",y:"2",rx:"2",ry:"2",key:"1yt0o3"}],["path",{d:"M12 18h.01",key:"mhygvu"}]]);var f=c(64308),g=c(94328);let h=(0,d.A)("credit-card",[["rect",{width:"20",height:"14",x:"2",y:"5",rx:"2",key:"ynyp8z"}],["line",{x1:"2",x2:"22",y1:"10",y2:"10",key:"1b3vmo"}]]);var i=c(75770);let j=(0,d.A)("sun",[["circle",{cx:"12",cy:"12",r:"4",key:"4exip2"}],["path",{d:"M12 2v2",key:"tus03m"}],["path",{d:"M12 20v2",key:"1lh1kg"}],["path",{d:"m4.93 4.93 1.41 1.41",key:"149t6j"}],["path",{d:"m17.66 17.66 1.41 1.41",key:"ptbguv"}],["path",{d:"M2 12h2",key:"1t8f8n"}],["path",{d:"M20 12h2",key:"1q8mjw"}],["path",{d:"m6.34 17.66-1.41 1.41",key:"1m8zz5"}],["path",{d:"m19.07 4.93-1.41 1.41",key:"1shlcs"}]]),k=[{slug:"jeddah-airport-sim-card",category:"arrival",icon:e,title:"SIM Card Guide at Jeddah Airport",titleAr:"دليل الشريحة في مطار جدة",summary:"Exactly where to buy local 5G eSIMs from stc, Mobily, or Zain at Terminal 1 and the North Terminal upon landing.",date:"May 12, 2026",readTime:"4 min",tags:["Jeddah","SIM Card","Airport Tips"],content:["stc (STC) booths are located immediately after baggage claim on the right — best 5G coverage nationwide.","Mobily kiosks are available in the arrivals hall — cheaper data plans, good for short stays.","Zain counters open 24/7 near exit gates — ask for the 'Hajj & Umrah' tourist SIM for pilgrim bundles.","eSIM: Use the stc or Zain app to activate a digital SIM before landing for seamless arrival connectivity.","Price range: SAR 60–150 depending on data bundle (10GB to Unlimited monthly).","Documents: bring your passport — a local SIM registration is mandatory in Saudi Arabia and takes 2–3 minutes at the counter.","Fingerprint scan: Saudi law requires a fingerprint scan for every active SIM, alongside your passport — the kiosk staff handle this as part of registration.","Coverage tip: stc has the strongest 5G across Makkah, Madinah, and the Haramain corridor — ideal if you are travelling for Umrah."],tldr:"You can buy a local 5G SIM (stc, Mobily, or Zain) right after baggage claim at Jeddah Airport. Bring your passport for registration, expect to pay SAR 60–150 for a tourist data bundle, or activate an eSIM before you land for instant connectivity.",tldrFacts:[{label:"Where",value:"After baggage claim"},{label:"Price",value:"SAR 60–150"},{label:"Best 5G",value:"stc"},{label:"Need",value:"Passport"}],faqs:[{question:"Where can I buy a SIM card at Jeddah Airport?",answer:"stc, Mobily, and Zain booths are located in the arrivals hall right after baggage claim in Terminal 1. Zain counters near the exit gates are open 24/7 for late-night flights."},{question:"How much does a tourist SIM cost in Jeddah?",answer:"A tourist data SIM costs between SAR 60 and SAR 150 depending on the bundle, ranging from 10GB up to unlimited monthly data. Pilgrim 'Hajj & Umrah' bundles are also available."},{question:"Do I need my passport to buy a SIM in Saudi Arabia?",answer:"Yes. SIM registration is mandatory in Saudi Arabia, so bring your passport — the counter staff will also take a fingerprint scan as part of registration, which is a legal requirement for every active SIM. The whole process takes 2–3 minutes."},{question:"Can I use an eSIM instead of a physical SIM?",answer:"Yes. You can activate an stc or Zain eSIM through their app before you land, so you have data the moment you arrive — useful for contacting your pre-booked driver."}]},{slug:"riyadh-to-bahrain-taxi-vs-train",category:"business",icon:f.A,title:"Riyadh to Bahrain: Taxi vs Train — Which Should You Choose?",titleAr:"الرياض إلى البحرين: تاكسي أم قطار؟",summary:"There is no direct train between Riyadh and Bahrain yet — here's why, and how a private transfer via the King Fahd Causeway compares to flying or the bus.",date:"Aug 11, 2026",readTime:"5 min",tags:["Riyadh","Bahrain","Cross-Border","Business Travel"],content:["There is no direct train between Riyadh and Bahrain today. The GCC's planned Gulf Railway network — intended to eventually connect Saudi Arabia, Bahrain, and other Gulf states — has not been completed on this route, so anyone searching for a 'Riyadh to Bahrain train' will not find one currently in service.","The only land link between Saudi Arabia and Bahrain is the King Fahd Causeway, a bridge-and-causeway road connecting the Eastern Province (near Al Khobar and Dammam) to Manama. All road travel — private transfer, bus, or private car — crosses here, with passport and border formalities at the Saudi and Bahraini checkpoints.","A private transfer from Riyadh to Manama covers about 450 km and takes roughly 4.5 hours including the Causeway crossing, fare confirmed on WhatsApp, with a professional driver who handles the route door-to-door from your Riyadh address to your Manama hotel or destination.","Flying is faster in the air, but by the time you add airport check-in, security, and transfer time on both ends, a private transfer is often comparable door-to-door for a Riyadh city departure — without needing to route through King Khalid International Airport specifically.","A public intercity bus is typically the lowest-cost option but runs on a fixed schedule, makes stops, and doesn't offer door-to-door pickup — a private transfer is the better choice if you're travelling with family, colleagues, or heavy luggage and want a departure time that suits you.","For business travellers and corporate accounts, a private transfer also allows working during the journey and crossing the Causeway without changing vehicles — something neither a bus nor a flight can offer."],tldr:"There is currently no train between Riyadh and Bahrain — the Gulf Railway connecting GCC states hasn't been completed on this route. The practical options are a private transfer via the King Fahd Causeway (about 4.5 hours door-to-door, fare confirmed on WhatsApp), a short flight, or a public bus. A private transfer is the most comfortable and flexible choice for families, business travellers, and anyone crossing with luggage.",tldrFacts:[{label:"Train available?",value:"No — not yet built"},{label:"Taxi time",value:"~4.5 hours door-to-door"},{label:"Taxi price",value:"Quoted on WhatsApp"},{label:"Best for",value:"Comfort & flexibility"}],faqs:[{question:"Is there a train from Riyadh to Bahrain?",answer:"No. There is currently no operational train line between Riyadh and Bahrain. The GCC's planned Gulf Railway network has not been completed on this route. The practical options today are a private transfer, flight, or public bus, with all road travel crossing via the King Fahd Causeway."},{question:"How long does it take to drive from Riyadh to Bahrain?",answer:"A private transfer from Riyadh to Manama, Bahrain takes about 4.5 hours covering roughly 450 km, including the King Fahd Causeway crossing and border formalities."},{question:"How much does a taxi from Riyadh to Bahrain cost?",answer:"A private transfer from Riyadh to Manama has its fare confirmed on WhatsApp before booking, with time for the Causeway crossing planned into the pickup."},{question:"What documents do I need to cross into Bahrain from Saudi Arabia?",answer:"A valid passport and the correct Bahrain entry eligibility or visa. Share your details in advance when booking so we can help prepare for a smooth crossing at the King Fahd Causeway."},{question:"Is a taxi or flight better for Riyadh to Bahrain?",answer:"A private transfer is often more convenient for door-to-door travel, especially with family or luggage, since it avoids airport check-in and transfer time. A flight is faster in the air but adds airport time on both ends."}]},{slug:"meeqat-locations",category:"umrah",icon:g.A,title:"Complete Meeqat Locations Guide for Umrah",titleAr:"دليل مواقيت العمرة الكامل",summary:"Step-by-step guidance on all 5 Meeqat points for international pilgrims arriving by air or road — including Dhul Hulaifah and Yalamlam.",date:"May 8, 2026",readTime:"7 min",tags:["Umrah","Meeqat","Pilgrim Guide"],content:["Dhul Hulaifah (Abyar Ali): For pilgrims from Madinah — enter ihram before departing to Makkah.","Al-Juhfah (Rabigh): For pilgrims from Syria, Jordan, and Egypt — most international flights connect via Jeddah and the Meeqat is near Rabigh.","Yalamlam: For pilgrims from Yemen and those arriving by sea on the western side.","Qarn Al-Manazil (As-Sayl): For pilgrims from Najd and those flying into Taif airport.","Dhat Irq: For pilgrims from Iraq — eastern approach to Makkah.","Pro Tip: If you're flying into Jeddah, you must enter ihram on the aircraft before crossing the Meeqat boundary — the crew will announce it.","By road: if you travel by car, a pre-booked taxi can stop at your relevant Meeqat so you enter ihram and pray before continuing to Makkah."],tldr:"There are five Meeqat boundaries where pilgrims must enter ihram before heading to Makkah. Your Meeqat depends on your direction of arrival — Dhul Hulaifah for Madinah, Al-Juhfah (Rabigh) for those via Jeddah by road, Yalamlam from the south, Qarn Al-Manazil from Taif/Najd, and Dhat Irq from Iraq.",tldrFacts:[{label:"From Madinah",value:"Dhul Hulaifah"},{label:"Via Jeddah (road)",value:"Al-Juhfah"},{label:"From Taif",value:"Qarn Al-Manazil"},{label:"By air",value:"Ihram on plane"}],faqs:[{question:"How many Meeqat points are there for Umrah?",answer:"There are five Meeqat boundaries: Dhul Hulaifah (Abyar Ali), Al-Juhfah, Yalamlam, Qarn Al-Manazil (As-Sayl), and Dhat Irq. The one that applies to you depends on your direction of travel to Makkah."},{question:"Which Meeqat applies if I arrive via Jeddah?",answer:"If you fly in, you enter ihram on the aircraft before the Meeqat is crossed. If you travel by road from the Jeddah/Rabigh direction, the relevant land Meeqat is Al-Juhfah, near Rabigh."},{question:"What is the Meeqat for pilgrims coming from Madinah?",answer:"Pilgrims travelling from Madinah enter ihram at Dhul Hulaifah, also called Abyar Ali, about 14 km from Masjid an-Nabawi by road, on the route to Makkah."},{question:"Can a taxi stop at the Meeqat on the way to Makkah?",answer:"Yes. On an intercity transfer your driver can stop at your relevant Meeqat so you change into ihram and pray two rak'ahs before continuing to Makkah."}]},{slug:"saudi-riyal-pilgrim-guide",category:"money",icon:h,title:"Saudi Riyal Cash & Card Tips for Pilgrims",titleAr:"نصائح العملة للحجاج والزوار",summary:"Everything about card acceptance, the local Mada network, currency exchange outlets, and ATM fee limits in KSA.",date:"April 29, 2026",readTime:"5 min",tags:["Money","Currency","Finance"],content:["ATMs: Use Al-Rajhi, Al-Ahli (ANB), or Riyad Bank ATMs — lowest international withdrawal fees (typically SAR 15–20 per transaction).","Mada network: All local debit transactions. Most shops accept international Visa/MC contactless.","Apple Pay & Google Pay are widely accepted in Riyadh, Jeddah, and major malls — even for small purchases.","Currency exchange: Best rates at airport exchange desks (not the first booth you see). Travelex rates are 5–8% worse than local exchangers.","Cash is still king in Makkah/Madinah small shops, taxis, and street vendors. Carry at least SAR 500–1000 in small notes.","Emergency: Western Union and MoneyGram are available at most Saudi Post branches.","Tipping: not mandatory, but rounding up a taxi fare or tipping SAR 10–20 for good service is appreciated."],tldr:"Saudi Arabia is largely cashless in cities — Visa, Mastercard, Apple Pay, and Google Pay work almost everywhere via the Mada network. Use Al-Rajhi, ANB, or Riyad Bank ATMs for the lowest withdrawal fees, but carry SAR 500–1000 in small notes for taxis and small shops in Makkah and Madinah.",tldrFacts:[{label:"Cards",value:"Widely accepted"},{label:"ATM fee",value:"~SAR 15–20"},{label:"Carry cash",value:"SAR 500–1000"},{label:"Apple Pay",value:"Yes"}],faqs:[{question:"Can I use my credit card everywhere in Saudi Arabia?",answer:"In cities, yes — international Visa and Mastercard, plus Apple Pay and Google Pay, are accepted at most shops, hotels, and malls. Carry some cash for small shops, street vendors, and some taxis in Makkah and Madinah."},{question:"Which ATMs have the lowest fees in Saudi Arabia?",answer:"Al-Rajhi, Al-Ahli (ANB), and Riyad Bank ATMs typically charge the lowest international withdrawal fees, usually around SAR 15–20 per transaction."},{question:"How much cash should pilgrims carry?",answer:"Carry at least SAR 500–1000 in small notes (50 and 100 denominations) for taxis, tips, and small purchases near the Haram, where card acceptance can be limited."},{question:"Where can I exchange currency at the best rate?",answer:"Local exchange houses usually offer better rates than the first airport booth you see. Compare a couple of desks; rates at high-street currency brands can be 5–8% worse than local exchangers."}]},{slug:"jeddah-airport-guide",category:"arrival",icon:i.A,title:"Jeddah Airport Terminals: Terminal 1, Terminal 4, North Terminal and Hajj Terminal",metaTitle:"Jeddah Airport Terminals: Terminal 1, T4, North & Hajj",titleAr:"دليل صالات مطار الملك عبدالعزيز في جدة",summary:"Terminal 1, new Terminal 4, North Terminal and Hajj Terminal at Jeddah airport (JED) explained, with the airline moves reported since September 2026.",date:"April 21, 2026",updated:"16 November 2026",readTime:"7 min",tags:["Jeddah","Airport","Terminals"],content:["Terminal 1 is the main hub for international and domestic flights, including Saudia.","Terminal 4 began a phased opening on 27 September 2026, and foreign airlines are moving there from the North Terminal.","Reports say all North Terminal flights move to Terminal 4 and the Hajj and Umrah Terminals from 17 October 2026.","The terminals are separate buildings and assignments are still changing, so confirm your terminal with your airline.","Makkah is about 80 km (around 1 hour) from the airport; Madinah is about 420 km (4 to 5 hours)."],tldr:"King Abdulaziz International Airport (JED) has Terminal 1, the new Terminal 4, the North Terminal and the Hajj and Umrah Terminal. Terminal 1 is the main hub, Terminal 4 began opening in phases on 27 September 2026, and the North Terminal's foreign airlines are being moved to Terminal 4 and the Hajj and Umrah Terminals. Assignments are still changing, so confirm your terminal with your airline before you travel.",tldrFacts:[{label:"Main hub",value:"Terminal 1"},{label:"New",value:"Terminal 4 (from 27 Sep 2026)"},{label:"To Makkah",value:"~80 km, ~1 hr"},{label:"Pickup",value:"Meet & greet at arrivals"}],sections:[{heading:"Which terminal does my flight use at Jeddah airport?",body:["Your airline decides, and the answer has been changing since September 2026, so check it on your ticket or the airline's app before you leave and again a day before you land. Your ticket may still show the North Terminal even after the move, so a quick confirmation with the airline is worth it.","The table below sets out what each terminal is for, based on press reports published between September and November 2026. It is a guide to the layout, not a flight-by-flight list."],table:{head:["Terminal","What it is","Who uses it"],rows:[["Terminal 1","The main hub for international and domestic flights. Opened in 2019, with the Haramain high-speed rail station connected to it.","Saudia and many other carriers. Selected carriers from Terminal 1 are part of the relocation plan."],["Terminal 4","The newest terminal: about 97,000 square metres, up to 15 million passengers a year, with a dedicated group check-in area for Hajj and Umrah pilgrims. Phased opening began on 27 September 2026.","Foreign airlines moving from the North Terminal, such as Wizz Air, AJet and SalamAir, plus other carriers as the move continues."],["North Terminal","The terminal that handled most foreign airlines. Reports say its flights move to Terminal 4 and the Hajj and Umrah Terminals from 17 October 2026.","Being phased out; some tickets may still show it."],["Hajj and Umrah Terminal","A separate terminal for pilgrim flights, distinct from Terminal 4.","Pilgrim and charter operations, and several airlines moved there from the North Terminal."]]},note:"Sources: Khaleej Times (17 October 2026), Gulf News (27 September 2026) and Wego (1 October 2026, updated 2 November 2026). Terminal assignments change; the airline's own booking information is the final word."},{heading:"What is Terminal 4 at Jeddah airport?",body:["Terminal 4 is the new terminal at King Abdulaziz International Airport, about 97,000 square metres with room for up to 15 million passengers a year. Its phased opening began on 27 September 2026, and it includes a dedicated group check-in area for Hajj and Umrah pilgrims.","Wizz Air, AJet and SalamAir were the first airlines to move in on 27 September. Fly Jinnah, Nesma Airlines, Akasa Air, SyrianAir, Pegasus, Azerbaijan Airlines and Tunisair followed between 28 September and 3 October. Other airlines are moving gradually as operations allow."]},{heading:"Is the North Terminal at Jeddah airport still used?",body:["The North Terminal is being phased out. Khaleej Times reported on 17 October 2026 that all flights from the North Terminal move to Terminal 4 and the Hajj and Umrah Terminals, effective 17 October.","Wego reported seven airlines assigned to the Hajj and Umrah Terminal from the North Terminal: Tarco Aviation, Yemenia, SCAT Airlines, Uzbekistan Airways, Daallo Airlines, Somon Air and Sudan Airways. If your ticket says North Terminal, confirm the current terminal with your airline before you book a pickup."]},{heading:"Which Jeddah airport terminal is for Umrah and Hajj flights?",body:["Pilgrim flights use the Hajj and Umrah Terminal and, since September 2026, Terminal 4, which has its own group check-in area for pilgrims. Many Umrah travellers also arrive through Terminal 1 on scheduled flights, so the terminal depends on the airline, not on the purpose of your trip.","Jeddah lies inside the Miqat boundary, so pilgrims arriving by air usually enter Ihram on the plane before landing. Our Miqat guide explains the details and what to do if you need the Al-Juhfah Miqat near Rabigh."]},{heading:"How do I meet my driver at Jeddah airport?",body:["Your driver provides meet and greet at arrivals. Send us your flight number and the terminal your airline shows when you book, and tell us if the terminal changes before you fly.","We track your flight, so a delay simply moves the pickup to your actual landing time, and 15 to 30 minutes of waiting after landing is free. The terminals are separate buildings, so a message to correct the terminal saves you a long walk or a second transfer."]},{heading:"How far is Jeddah airport from Makkah and Madinah?",body:["Makkah is about 80 km from Jeddah airport, roughly one hour by road, and Madinah is about 420 km, roughly four to five hours. A private car goes straight from your terminal to your hotel on your schedule, with prayer and rest stops on request."],table:{head:["Option","Best when","Trade-off"],rows:[["Private car with driver","Families, groups, heavy luggage, late-night arrivals, or a hotel that is not beside a station","Door to door on your schedule; the fare is agreed on WhatsApp before you book"],["Haramain high-speed train","Light luggage and a hotel close to a station; the Jeddah airport station is connected to Terminal 1, about 45 minutes to Makkah and about 1 hour 45 minutes to Madinah","Station to station; you arrange the last stretch to your hotel, and a terminal other than Terminal 1 means getting to Terminal 1 first"]]},note:"Train times from SPA via seo/venues.md. Check the current timetable with the operator."}],faqs:[{question:"Which terminal do international flights use at Jeddah airport?",answer:"Terminal 1 is the main hub for international and domestic flights, including Saudia. Since September 2026, foreign airlines have also been moving to the new Terminal 4. Confirm your terminal with your airline, because assignments are still changing."},{question:"What is the difference between Terminal 1 and the North Terminal at Jeddah airport?",answer:"Terminal 1 is the main hub and opened in 2019. The North Terminal handled most foreign airlines and is being phased out, with its flights moving to Terminal 4 and the Hajj and Umrah Terminals from 17 October 2026, according to Khaleej Times."},{question:"Is Terminal 4 open at Jeddah airport?",answer:"Yes, in phases. Terminal 4 began opening on 27 September 2026 with Wizz Air, AJet and SalamAir, and other airlines have been moving since. It covers about 97,000 square metres and is designed for up to 15 million passengers a year."},{question:"Which terminal is the Hajj terminal at Jeddah airport?",answer:"The Hajj and Umrah Terminal is a separate terminal for pilgrim flights, distinct from Terminal 4. Terminal 4 also has a dedicated group check-in area for pilgrims. Your airline confirms which one your flight uses."},{question:"How do I find my driver at Jeddah airport?",answer:"Your driver provides meet and greet at arrivals. Share your flight number and the terminal your airline shows when you book, and tell us if it changes before you fly so the driver waits at the right place."},{question:"What happens if my flight to Jeddah is delayed?",answer:"We track your flight, so a delay moves the pickup to your actual landing time. Free waiting of 15 to 30 minutes after landing applies, so you are not charged for the time it takes to clear immigration and collect bags."},{question:"How far is Jeddah airport from Makkah and Madinah?",answer:"Makkah is about 80 km, roughly one hour. Madinah is about 420 km, roughly four to five hours. A pre-booked private car takes you straight from your terminal to your hotel, with the fare confirmed on WhatsApp before you book."},{question:"Should I take the train or a private car from Jeddah airport to Makkah?",answer:"The Haramain train suits light luggage and a hotel near a station; the airport station connects to Terminal 1. A private car suits families, groups, heavy bags and late arrivals, and takes you door to door at a fare agreed before you travel."}],cta:{heading:"Arriving at Jeddah airport?",text:"Send your flight number, the terminal your airline shows and where you are going. We confirm the fare on WhatsApp before you book, and cancellation is free up to 24 hours before pickup.",waText:"Salam! Jeddah airport pickup enquiry.\n• Flight number & arrival time: \n• Terminal shown by my airline: \n• Going to (Makkah / Madinah / Jeddah hotel): \n• Passengers & luggage: \n• Vehicle (Sedan / SUV / Van): "}},{slug:"umrah-packing-checklist",category:"umrah",icon:g.A,title:"The Ultimate Umrah Packing List",titleAr:"قائمة تجهيزات العمرة الشاملة",summary:"From ihram garments to medication and digital essentials — a complete packing checklist for pilgrims performing Umrah.",date:"April 15, 2026",readTime:"8 min",tags:["Umrah","Packing","Preparation"],content:["Ihram: 2 sets minimum (one to wear, one clean backup). Seamless white cotton — available at Jeddah airport too.","Footwear: Rubber sandals with no back-strap for men. Comfortable closed shoes for women.","Medications: Paracetamol, electrolyte sachets, blister pads, anti-diarrheal tablets, and any prescription drugs (with Arabic prescription copies).","Digital: Saudi eVisa saved on your phone (offline), booking confirmations, emergency contacts.","Cash: Carry SAR 500–1000 in notes of 50 and 100 denomination.","Zamzam: You're allowed 5 liters in checked luggage on departure — available free from dispensers throughout the Haram.","Documents: keep your passport, eVisa, vaccination certificate, and hotel and transfer bookings in one folder plus an offline phone copy."],tldr:"Pack two sets of ihram, comfortable backless sandals, a small medical kit (paracetamol, electrolytes, blister pads), unscented toiletries, and SAR 500–1000 in small notes. Keep your passport, eVisa, and booking confirmations together, and remember you can carry up to 5 litres of Zamzam in checked luggage on departure.",tldrFacts:[{label:"Ihram sets",value:"2 minimum"},{label:"Toiletries",value:"Unscented"},{label:"Cash",value:"SAR 500–1000"},{label:"Zamzam",value:"5L checked"}],faqs:[{question:"What should I pack for Umrah?",answer:"Bring two sets of ihram, backless sandals, unscented toiletries, a small medical kit, your passport and eVisa, booking confirmations, and SAR 500–1000 in small notes. Modest clothing for non-ihram times is also recommended."},{question:"Can I bring medication for Umrah?",answer:"Yes. Pack essentials like paracetamol, electrolyte sachets, blister pads, and anti-diarrheal tablets. Carry prescription medicines in their original packaging with an Arabic prescription copy where possible."},{question:"How much Zamzam water can I take home?",answer:"You are generally allowed up to 5 litres of Zamzam in checked luggage on departure. It is available free from dispensers throughout the Haram — do not pack it in hand luggage."},{question:"Why are unscented toiletries important during Umrah?",answer:"While in ihram, perfumed or scented products are not permitted. Pack unscented soap, shampoo, and deodorant so you stay within the rules of ihram."}]},{slug:"saudi-customs-pilgrims",category:"culture",icon:j,title:"Saudi Arabia — Customs, Etiquette & Laws for Visitors",titleAr:"العادات والقوانين للزوار في المملكة",summary:"Essential cultural norms, dress codes, photography rules, and things to know before entering the Kingdom as a tourist or pilgrim.",date:"April 8, 2026",readTime:"6 min",tags:["Culture","Laws","Saudi Arabia"],content:["Dress code: Modest clothing required in holy areas. Women are no longer required to wear abaya in public but modest dress is encouraged.","Photography: NEVER photograph government buildings, military sites, or people without permission. The Haram interior photography is restricted.","Alcohol: Strictly prohibited. Zero tolerance — criminal penalties apply.","Prayer times: Many shops close briefly during Salah. Build 15–20 minute buffers into schedules.","Ramadan: Business hours shift significantly. Eating/drinking in public during daylight hours is illegal for all.","Respect: Stand when national anthem plays, remove shoes before entering mosques, greet with 'As-salamu alaykum'.","Public conduct: public displays of affection are frowned upon, and queuing and politeness with officials go a long way."],tldr:"Saudi Arabia welcomes tourists and pilgrims but expects modest dress, respect for prayer times, and strict adherence to local laws. Alcohol is completely banned, photographing people or government and military sites without permission is prohibited, and modest clothing is required around the holy sites.",tldrFacts:[{label:"Alcohol",value:"Prohibited"},{label:"Dress",value:"Modest"},{label:"Photos",value:"Ask first"},{label:"Prayer times",value:"Shops pause"}],faqs:[{question:"What should tourists wear in Saudi Arabia?",answer:"Modest clothing is expected, especially around the holy sites. Women are no longer required to wear an abaya in public but should dress modestly; men should avoid shorts in religious areas."},{question:"Is alcohol allowed in Saudi Arabia?",answer:"No. Alcohol is strictly prohibited with zero tolerance, and criminal penalties apply for possession or consumption."},{question:"Can I take photos freely in Saudi Arabia?",answer:"Avoid photographing people without permission, and never photograph government buildings or military sites. Photography inside the Haram is restricted."},{question:"How do prayer times affect daily life?",answer:"Many shops pause briefly during each of the five daily prayers, so build 15–20 minute buffers into your schedule. During Ramadan, eating or drinking in public during daylight hours is not permitted."}]},{slug:"riyadh-business-travel",category:"business",icon:f.A,title:"Riyadh Business District Navigator",titleAr:"دليل الأحياء التجارية في الرياض",summary:"KAFD, Olaya, Diplomatic Quarter, and King Abdullah Financial District — your executive's guide to navigating Riyadh's business zones.",date:"March 30, 2026",readTime:"5 min",tags:["Riyadh","Business","Corporate"],content:["KAFD (King Abdullah Financial District): Ultra-modern skyscraper district in north Riyadh — home to major banks, PIF, and global firms.","Olaya Street: The traditional business heart — major hotels (Four Seasons, Ritz-Carlton), restaurants, and corporate towers.","Diplomatic Quarter (DQ): Embassies, international schools, and secure residential compounds. Strict access controls.","Al Faisaliah Tower: Iconic landmark — conference facilities, restaurants, and executive suites.","Traffic: Riyadh rush hours are 7–9am and 4–8pm. Allow 45-min buffers for cross-city transfers during peak.","driver tip: Pre-book your Taxi Saudi Arabia driver for the full meeting day — hourly charter saves time and avoids Uber surge pricing.","Airport: King Khalid International Airport (RUH) is about 35 km north of the city — allow 45–60 minutes to KAFD or Olaya during peak hours."],tldr:"Riyadh's main business zones are KAFD (King Abdullah Financial District) in the north, Olaya Street in the centre, and the Diplomatic Quarter. Rush hours are 7–9am and 4–8pm, so allow 45-minute buffers between meetings, and pre-book an hourly chauffeur for a full meeting day to avoid surge pricing.",tldrFacts:[{label:"Finance hub",value:"KAFD"},{label:"Central",value:"Olaya"},{label:"Airport",value:"RUH (~35 km)"},{label:"Rush hour",value:"7–9am, 4–8pm"}],faqs:[{question:"What are the main business districts in Riyadh?",answer:"The key zones are KAFD (King Abdullah Financial District) in north Riyadh, Olaya Street in the centre with major hotels and towers, and the Diplomatic Quarter for embassies and international organisations."},{question:"How do I get around Riyadh for business meetings?",answer:"Pre-booking an hourly chauffeur for the day is the most efficient option — your driver waits between meetings, knows the fastest routes, and you avoid ride-hailing surge pricing during peak hours."},{question:"How far is Riyadh airport from the business districts?",answer:"King Khalid International Airport (RUH) is about 35 km north of the city. Allow 45–60 minutes to KAFD or Olaya during morning and evening rush hours."},{question:"When is Riyadh traffic at its worst?",answer:"Rush hours are roughly 7–9am and 4–8pm. Build 45-minute buffers into cross-city transfers during these windows to stay on schedule."}]},{slug:"alula-transport-guide",category:"tourism",icon:f.A,title:"AlUla Visitor Guide — Hegra, Dadan & the Rose City",titleAr:"دليل زيارة العلا — الحجر ودادان",summary:"What to see in AlUla — Hegra's 111 Nabataean tombs, Dadan, Jabal Ikmah and Elephant Rock — the best season to visit (October to March), and how far apart the sites are.",date:"March 20, 2026",readTime:"9 min",tags:["AlUla","Tourism","Heritage"],content:["Hegra (Mada'in Salih): Saudi Arabia's first UNESCO World Heritage Site — 111 Nabataean tombs carved from rose sandstone.","Dadan: The ancient capital of the Dadanite kingdom — predates Hegra. Guided access only via AlUla Experience tours.","Jabal Ikmah: Open-air library of ancient inscriptions — largest in the Arabian Peninsula.","Elephant Rock (Jabal Al-Fil): A natural rock formation resembling an elephant — free access, stunning at sunset.","Best time to visit: October to March — temperatures between 15–25\xb0C. Avoid summers (40\xb0C+).","Getting there: Direct flights from Riyadh/Jeddah to ULH Airport, or a premium road transfer (~10 hours from Riyadh).","Getting around AlUla: sites are spread out across the valley, so a private car or guided transfer is the most comfortable way to link Hegra, Dadan, and the Old Town."],tldr:"AlUla is home to Saudi Arabia's first UNESCO World Heritage Site, Hegra, with 111 Nabataean tombs, plus Dadan, Jabal Ikmah, and Elephant Rock. Visit between October and March for mild weather, fly into AlUla (ULH) Airport, and use a private car to link the widely spread sites comfortably.",tldrFacts:[{label:"UNESCO site",value:"Hegra"},{label:"Best season",value:"Oct–Mar"},{label:"Airport",value:"ULH"},{label:"Getting around",value:"Private car"}],faqs:[{question:"What is there to see in AlUla?",answer:"The highlights are Hegra (Mada'in Salih), a UNESCO World Heritage Site with 111 Nabataean tombs, the ancient city of Dadan, the inscriptions at Jabal Ikmah, and the natural Elephant Rock formation."},{question:"When is the best time to visit AlUla?",answer:"October to March, when daytime temperatures are a comfortable 15–25\xb0C. Summers regularly exceed 40\xb0C and are best avoided for outdoor sightseeing."},{question:"How do I get to AlUla?",answer:"You can fly directly into AlUla (ULH) Airport from Riyadh or Jeddah, or take a premium road transfer — roughly 10 hours from Riyadh or around 3 hours from Madinah."},{question:"How do I get around AlUla's attractions?",answer:"The sites are spread across the valley, so a private car or guided transfer is the most comfortable way to link Hegra, Dadan, Jabal Ikmah, and the resorts at your own pace."}]},{slug:"jeddah-airport-to-makkah-guide",category:"umrah",icon:i.A,title:"Jeddah Airport to Makkah: Complete Transfer Guide (Taxi, Train & Bus)",titleAr:"دليل الانتقال من مطار جدة إلى مكة",summary:"Transfer options from Jeddah Airport (JED) to Makkah — taxi, Haramain train & bus — covering travel times, costs, & Miqat advice for pilgrims.",date:"June 25, 2026",readTime:"7 min",tags:["Jeddah","Makkah","Umrah","Airport"],tldr:"King Abdulaziz International Airport (JED) is about 80 km from Makkah — roughly a 1-hour drive. A pre-booked private transfer is the most direct option (door-to-door, fare confirmed on WhatsApp, 24/7, with a Miqat stop for Ihram on request). The Haramain high-speed train has a station at the airport, but Makkah station is not beside the Haram, so you still need a car for the last leg.",tldrFacts:[{label:"Distance",value:"~80 km"},{label:"Taxi time",value:"~1 hour"},{label:"Taxi price",value:"Quoted on WhatsApp"},{label:"Train",value:"Airport station + taxi at Makkah end"}],content:["Distance & time: JED is about 80 km from Makkah on the Makkah Expressway (Highway 40) — a private transfer takes roughly 1 hour door-to-door, traffic permitting.","Option 1 — Private transfer (most popular): Pre-booked, fare confirmed on WhatsApp, available 24/7. Your driver meets you at arrivals, helps with luggage, and drops you at your Makkah hotel. Best for pilgrims with luggage, families, and late-night flights.","Option 2 — Haramain High-Speed Railway: Since December 2019 the line has a station at King Abdulaziz International Airport (a 3.75 km branch off the main line), so you can board near the terminal. Makkah station, however, is not next to the Haram — you still need a taxi from the station to your hotel, and the train has luggage limits, which matters for pilgrims carrying several large bags.","Option 3 — Bus / shared transport: Cheapest but slowest, with fixed schedules and multiple stops. Not ideal after a long international flight.","Option 4 — Airport taxi rank or ride-hailing app: available on arrival, but you need mobile data for an app, pick-up is from designated zones, and the price is not agreed in advance the way a pre-booked transfer is.","Ihram & Miqat: If you arrive in Jeddah intending Umrah, you must be in Ihram before crossing the Miqat boundary. On flights the crew announces the Miqat so you can enter Ihram on board; if you land without it, a taxi can stop at the Miqat (Al-Juhfah, near Rabigh) before continuing to Makkah.","On arrival at JED: clear immigration, collect baggage, buy a local SIM if needed, then meet your pre-booked driver in the arrivals hall. Pre-booking avoids airport queues and surge pricing.","Keep documents to hand: there is a security checkpoint on the road before Makkah, so keep passports and your hotel confirmation accessible rather than packed in the boot.","Best choice for most pilgrims: a pre-booked private transfer — it is direct, handles luggage, runs 24/7, and allows a Miqat stop for Ihram without extra planning."],faqs:[{question:"How far is Jeddah airport from Makkah?",answer:"King Abdulaziz International Airport (JED) is about 80 km from Makkah — roughly a 1-hour drive on the Makkah Expressway."},{question:"What is the cheapest way from Jeddah airport to Makkah?",answer:"Buses are the cheapest but slowest. For most pilgrims with luggage, a pre-booked private transfer is the best value because it is direct, door-to-door, and available 24/7 with no surge pricing — fare confirmed on WhatsApp before booking."},{question:"Can I take the Haramain train from Jeddah airport to Makkah?",answer:"Yes — the Haramain high-speed railway has a station at King Abdulaziz International Airport. Makkah station is not beside the Haram, though, so you still need a taxi from the station to your hotel, and luggage limits apply. Families with several large bags often find a direct car simpler."},{question:"Do I need to be in Ihram before reaching Makkah?",answer:"Yes. If you intend Umrah, you must enter Ihram before crossing the Miqat boundary. On the flight the crew announces the Miqat; if you land without Ihram, a taxi can take you to the Miqat at Al-Juhfah (near Rabigh, north of Jeddah) first, before driving to Makkah."}]},{slug:"miqat-jeddah-makkah",category:"umrah",icon:g.A,title:"Miqat & Ihram When Arriving via Jeddah (Step-by-Step)",titleAr:"الميقات والإحرام عند الوصول عبر جدة",summary:"Where and when to enter Ihram if you arrive in Jeddah for Umrah — the on-board Miqat announcement, Al-Juhfah (Rabigh), and exactly what to do if you land without Ihram.",date:"June 25, 2026",readTime:"6 min",tags:["Umrah","Miqat","Ihram","Jeddah"],tldr:"If you fly into Jeddah for Umrah, you must enter Ihram before crossing the Miqat — the aircraft crew announces it so you can make your intention on board. If you land without Ihram, the relevant Miqat is Al-Juhfah (near Rabigh, north of Jeddah), and a taxi can take you there first before driving to Makkah.",tldrFacts:[{label:"By air",value:"Ihram on the plane"},{label:"Road Miqat",value:"Al-Juhfah (Rabigh)"},{label:"To Makkah",value:"~80 km"},{label:"Taxi stop",value:"On request"}],content:["What the Miqat is: the Miqat is the boundary at which a pilgrim must already be in the state of Ihram before proceeding to Makkah for Umrah or Hajj.","Arriving by air into Jeddah: most international flights cross the Miqat boundary before landing, so you enter Ihram on the aircraft. The crew or captain announces when the Miqat is approaching — change into Ihram and make your intention (niyyah) before that point.","Jeddah is NOT a Miqat: the city of Jeddah lies inside the Miqat boundary, so you cannot wait until you land to enter Ihram if your flight has already crossed it.","If you land without Ihram: the designated land Miqat for those coming from the Jeddah/Rabigh direction is Al-Juhfah (near Rabigh), north of Jeddah. Scholars differ on the ruling for those who pass the air Miqat without Ihram, so many pilgrims choose to travel out to Al-Juhfah to enter Ihram to be safe.","Practical option from Jeddah Airport: there is no Miqat on the road from the airport to Makkah. If you landed without Ihram and choose to go to Al-Juhfah, book the car with that stop in advance — it lies north of Jeddah, the opposite direction from Makkah, so it is a long detour that is quoted separately.","Ihram essentials: wear the two white seamless garments (men), keep a clean backup set, and avoid prohibited acts (perfume, cutting hair/nails) once in Ihram.","After Ihram: continue to Makkah (~80 km, ~1 hour), check into your hotel, then proceed to Masjid al-Haram to perform Tawaf and Sa'i."],faqs:[{question:"Is Jeddah a Miqat for Umrah?",answer:"No. Jeddah lies inside the Miqat boundary, so it is not a Miqat. If you intend Umrah you must be in Ihram before crossing the Miqat — usually announced on your flight before landing in Jeddah."},{question:"Where do I enter Ihram if I arrive at Jeddah airport?",answer:"Normally on the aircraft, when the crew announces the Miqat. If you arrive without Ihram, the relevant land Miqat is Al-Juhfah (near Rabigh), and a taxi can take you there before heading to Makkah."},{question:"Can a taxi stop at the Miqat on the way to Makkah?",answer:"Yes. On the Jeddah Airport to Makkah transfer, tell the driver in advance and they will stop at the Miqat so you can change into Ihram and pray before continuing to Makkah."},{question:"What if I forgot to enter Ihram before the Miqat?",answer:"Rulings vary, so consult a scholar. Many pilgrims travel out to the nearest Miqat (Al-Juhfah for the Jeddah direction) to enter Ihram there to avoid any shortfall before performing Umrah."}]},{slug:"makkah-to-madinah-transport-guide",category:"umrah",icon:f.A,title:"Makkah to Madinah: Taxi vs Haramain Train vs Bus",titleAr:"من مكة إلى المدينة: تاكسي أم قطار الحرمين",summary:"Compare every way to travel from Makkah to Madinah — private transfer, Haramain high-speed train, and bus — with distance, time, cost, and comfort for pilgrims and families.",date:"June 25, 2026",readTime:"7 min",tags:["Makkah","Madinah","Umrah","Transport"],tldr:"Makkah to Madinah is about 430 km. A private transfer is door-to-door in roughly 4–5 hours (fare confirmed on WhatsApp) with prayer stops. The Haramain high-speed train covers it in about 2.5 hours but needs transfers to and from the stations.",tldrFacts:[{label:"Distance",value:"~430 km"},{label:"Taxi",value:"~4–5 hr, quoted on WhatsApp"},{label:"Train",value:"~2.5 hr + transfers"},{label:"Bus",value:"~6–7 hr"}],content:["Distance: Makkah to Madinah is about 430 km on the Haramain highway — a major, well-maintained route used by millions of pilgrims each year.","Option 1 — Private transfer (most flexible): door-to-door from your Makkah hotel to your Madinah hotel in roughly 4–5 hours, fare confirmed on WhatsApp, with prayer and rest stops included. Best for families, elderly pilgrims, and anyone with luggage.","Option 2 — Haramain High-Speed Railway: the train is fast (about 2.5 hours between stations), but you still need a taxi to the Makkah station and from the Madinah station to your hotel, plus check-in time — which adds up with luggage.","Option 3 — Intercity bus: the cheapest option at around 6–7 hours with fixed schedules and stops. Economical but slower and less comfortable after Umrah.","Comfort & timing: a private transfer lets you leave when you want, pray on the way, and arrive directly at your hotel near Masjid an-Nabawi — no transfers or waiting.","On the road: the Haramain highway is a multi-lane expressway monitored by Saher speed cameras, with large service stations (mahattat) along the way offering fuel, restrooms, prayer areas and food — natural places for a prayer or rest stop on a 4-hour drive.","Luggage: the train applies luggage size and weight limits; a private SUV or van carries a family's full Umrah luggage without repacking.","Best for most pilgrims: a private transfer for door-to-door comfort, or the Haramain train if you are travelling light and want the fastest station-to-station time."],faqs:[{question:"How far is Makkah from Madinah?",answer:"Makkah to Madinah is about 430 km — roughly a 4 to 5 hour drive by taxi on the Haramain highway, or about 2.5 hours station-to-station on the Haramain high-speed train."},{question:"Is the taxi or train better from Makkah to Madinah?",answer:"The train is faster between stations, but a private transfer is door-to-door from hotel to hotel with prayer stops and no transfers — usually more convenient for pilgrims with luggage or elderly travellers."},{question:"How much is a taxi from Makkah to Madinah?",answer:"A private transfer is available by sedan, SUV, or van for families. Your exact price is confirmed on WhatsApp before booking, with tolls included."},{question:"Are prayer stops included on the way to Madinah?",answer:"Yes — with a private transfer you can ask for stops for prayer, food and rest on the journey, and we plan them into the trip."}]},{slug:"makkah-hotel-haram-dropoff-guide",category:"umrah",icon:f.A,title:"Makkah Hotels & Haram Drop-off: What Pilgrims Should Know",titleAr:"فنادق مكة ونقاط النزول قرب الحرم",summary:"How taxi drop-offs work around Masjid al-Haram — hotel zones, prayer-time road closures, the closest permitted points, and tips for arriving smoothly with luggage.",date:"June 25, 2026",readTime:"5 min",tags:["Makkah","Haram","Hotels","Umrah"],tldr:"Around Masjid al-Haram, vehicle access is restricted — especially during prayer times. A taxi drops you at the closest permitted point to your hotel; central-area hotels (Ajyad, Clock Tower, Shubaikah) are within a short walk of the Haram.",tldrFacts:[{label:"Central hotels",value:"5–10 min walk"},{label:"Aziziyah",value:"~10 min drive"},{label:"Prayer times",value:"Road closures"},{label:"Drop-off",value:"Nearest permitted point"}],content:["Haram-adjacent hotels: districts like Ajyad, Al Shubaikah, and the Clock Tower (Abraj Al Bait) complex are within a 5–10 minute walk of Masjid al-Haram — the most convenient for frequent prayers.","Nearby hotel zones: Aziziyah and Al Awali are short drives (about 10–15 minutes) from the Haram, often better value and popular for longer Hajj/Umrah stays.","Prayer-time closures: roads immediately around the Haram close to vehicles during the five daily prayers and at peak times. Your driver will know the timing and use the nearest open checkpoint.","Drop-off points: a taxi drops you at the closest permitted security checkpoint to your hotel; from there it is a short walk. Travel light at the kerbside as porters and trolleys are available.","Arrival tip: share your hotel name and district when booking so the driver plans the best approach and avoids closed roads.","Departure tip: for your return to Jeddah Airport, pre-book and leave with buffer time — central-area pickups can be slower during prayer and peak hours."],faqs:[{question:"Can a taxi drop me at my hotel next to the Haram?",answer:"It drops you at the closest point vehicles are permitted. Many central hotels (Ajyad, Shubaikah, Clock Tower) are then a short 5–10 minute walk from Masjid al-Haram."},{question:"Why do taxis stop away from the Haram during prayer times?",answer:"Roads immediately around Masjid al-Haram close to vehicles during the daily prayers and at peak times for crowd safety. Your driver uses the nearest open checkpoint."},{question:"Which Makkah hotel area is closest to the Haram?",answer:"Ajyad, Al Shubaikah, and the Clock Tower (Abraj Al Bait) area are among the closest — typically a 5–10 minute walk. Aziziyah and Al Awali are short drives away."}]},{slug:"madinah-ziyarat-sites-guide",category:"umrah",icon:g.A,title:"Madinah Ziyarat: Holy Sites Guide & How to Visit by Car",titleAr:"دليل زيارة المدينة المنورة ومواقعها",summary:"The main Ziyarat sites in Madinah — Quba Mosque, Mount Uhud, Qiblatain Mosque, and the Seven Mosques — with distances and how to visit them comfortably by private car.",date:"June 25, 2026",readTime:"6 min",tags:["Madinah","Ziyarat","Umrah"],tldr:"The main Madinah Ziyarat sites — Quba Mosque, Mount Uhud, Qiblatain Mosque, and the Seven Mosques — are all within about 4–8 km of Masjid an-Nabawi. A half-day private car (about 3–4 hours) covers them comfortably with waiting time.",tldrFacts:[{label:"Quba Mosque",value:"~4 km"},{label:"Mount Uhud",value:"~6 km"},{label:"Qiblatain",value:"~7 km"},{label:"Tour",value:"~3–4 hours"}],content:["Quba Mosque (~4 km): the first mosque built in Islam. Praying two rak'ahs here carries great reward — a popular first stop on any Ziyarat tour.","Mount Uhud (~6 km): site of the Battle of Uhud and the resting place of the martyrs, including Hamza (RA). A reflective, historic stop.","Qiblatain Mosque (~7 km): the Mosque of the Two Qiblas, where the direction of prayer was changed towards the Kaaba.","The Seven Mosques (Al-Khandaq area): a cluster of small historic mosques near the site of the Battle of the Trench.","How to visit: a half-day private car (about 3–4 hours) links all the main sites with flexible waiting time, which is far easier than separate taxis — especially for families and elderly pilgrims.","Etiquette: dress modestly, keep prayer times in mind, and allow extra time at Quba and Uhud which can be busy. Your driver will advise the best order to avoid crowds.","Masjid an-Nabawi & the Rawdah: most pilgrims base their visit around Masjid an-Nabawi; check current Rawdah visit booking requirements via the official Nusuk app before you go."],faqs:[{question:"How long does a Madinah Ziyarat tour take?",answer:"A half-day Ziyarat tour by private car takes about 3–4 hours and covers Quba Mosque, Mount Uhud, Qiblatain Mosque, and the Seven Mosques, with waiting time at each site."},{question:"How far are the Ziyarat sites from Masjid an-Nabawi?",answer:"The main sites are close — Quba is about 4 km, Mount Uhud about 6 km, and Qiblatain about 7 km from Masjid an-Nabawi."},{question:"Is it better to book a car for Ziyarat or take separate taxis?",answer:"A private car for the half-day is usually better value and far more comfortable, as the driver waits at each site and links them in the best order — ideal for families and elderly pilgrims."}]},{slug:"dhul-hulaifah-miqat-madinah",category:"umrah",icon:g.A,title:"Dhul Hulaifah (Abyar Ali): the Miqat for Madinah Pilgrims",titleAr:"ميقات ذو الحليفة (آبار علي) لأهل المدينة",summary:"If you travel from Madinah to Makkah for Umrah, you enter Ihram at Dhul Hulaifah (Abyar Ali). Here is where it is, what to do, and how to ask for a stop there on a private transfer.",date:"June 25, 2026",readTime:"5 min",tags:["Umrah","Miqat","Madinah","Ihram"],tldr:"Pilgrims travelling from Madinah to Makkah for Umrah enter Ihram at Dhul Hulaifah (Abyar Ali), about 14 km from Masjid an-Nabawi by road (Saudi Press Agency, March 2026). On a private Madinah to Makkah transfer you can ask for a stop there when you book.",tldrFacts:[{label:"Miqat",value:"Dhul Hulaifah"},{label:"Also called",value:"Abyar Ali"},{label:"From Madinah",value:"~14 km"},{label:"To Makkah",value:"~430 km"}],content:["What it is: Dhul Hulaifah, also known as Abyar Ali, is the Miqat for people travelling from Madinah towards Makkah. It is the furthest Miqat from Makkah.","Where it is: about 14 km south-west of Masjid an-Nabawi by road, on the road towards Makkah — a short drive from the central Madinah hotels.","What to do there: there is a large mosque at the Miqat with facilities to change and pray. Make your intention (niyyah) for Umrah and enter Ihram before you continue past the Miqat.","By private car: on a Madinah to Makkah transfer, tell us when you book if you want a stop at Dhul Hulaifah and we confirm it as part of the quote. This guide is general transport information, not a religious ruling — follow qualified guidance for your own circumstances.","Ihram essentials: wear the two white seamless garments (men), avoid perfume and cutting hair or nails once in Ihram, and keep a clean backup set.","After the Miqat: continue to Makkah (~430 km, ~4 hours) with prayer and rest stops, then proceed to Masjid al-Haram for Tawaf and Sa'i."],faqs:[{question:"Where do pilgrims from Madinah enter Ihram?",answer:"At Dhul Hulaifah (Abyar Ali), about 14 km from Masjid an-Nabawi by road, on the route to Makkah. It is the designated Miqat for those travelling from Madinah."},{question:"Can a taxi stop at Dhul Hulaifah on the way to Makkah?",answer:"You can ask for a stop at Dhul Hulaifah when you book a Madinah to Makkah transfer, and we confirm it as part of the quote. Whether and how to enter Ihram there is a personal religious matter we cannot advise on."},{question:"How far is Dhul Hulaifah from Madinah?",answer:"Dhul Hulaifah (Abyar Ali) is about 14 km from Masjid an-Nabawi by road — a short drive on the route towards Makkah."}]}]},94328:(a,b,c)=>{c.d(b,{A:()=>d});let d=(0,c(59740).A)("heart",[["path",{d:"M2 9.5a5.5 5.5 0 0 1 9.591-3.676.56.56 0 0 0 .818 0A5.49 5.49 0 0 1 22 9.5c0 2.29-1.5 4-3 5.5l-5.492 5.313a2 2 0 0 1-3 .019L5 15c-1.5-1.5-3-3.2-3-5.5",key:"mvr1a0"}]])}};